// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(100);

        address caller = address(0x123);
        address referrer = address(0x456);

        vm.prank(caller);
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.prank(caller);
        c.collectDrugs(referrer);

        uint256 drugsUsed = 25_920_000;
        uint256 expectedBonus = drugsUsed / 5;

        assertTrue(c.claimedDrugs(referrer) == expectedBonus);
    }
}
